    public static function search(string $q): array
    {
        $q = mb_strtolower(trim($q));
        if (mb_strlen($q) < 2) {
            return [];
        }

        $prefixMatches = [];
        $substringMatches = [];

        foreach (self::$cityState as $city => $state) {
            $pos = mb_stripos($city, $q);
            if ($pos === false) {
                continue;
            }
            $label = $city . ', ' . $state;
            if ($pos === 0) {
                $prefixMatches[] = $label;
            } else {
                $substringMatches[] = $label;
            }
        }

        return array_slice(array_merge($prefixMatches, $substringMatches), 0, 15);
    }
}
